import java.util.*;public class Driver {public static void main(String[]a){Map<String,Integer> f=new TreeMap<>();for(String w:"Java is great and Java is fast. Fast code is clean code!".toLowerCase().split("\\W+"))f.merge(w,1,Integer::sum);f.entrySet().stream().sorted(Map.Entry.<String,Integer>comparingByValue().reversed()).forEach(e->System.out.printf("%-8s : %d%n",e.getKey(),e.getValue()));}}
